    const controller = new AbortController();

    async function load() {
        try {
            const [courseResponse, lessonsResponse] = await Promise.all([
                fetch("/api/course", {
                    signal: controller.signal
                }),
                fetch("/api/lessons", {
                    signal: controller.signal
                })
            ]);

