// courseService.js

export function calculateProgress(done, total) {
    if (
        typeof done !== "number" ||
        typeof total !== "number" ||
        done < 0 ||
        total < 0
    ) {
        throw new Error("Lesson values must be valid numbers.");
    }

    return total === 0
        ? 0
        : Math.round((done / total) * 100);
}

export function validateStudent(student) {
    if (
        !student ||
        typeof student.name !== "string" ||
        !student.name.trim()
    ) {
        throw new Error("Student name is required.");
    }

    if (
        typeof student.course !== "string" ||
        !student.course.trim()
    ) {
        throw new Error("Course name is required.");
    }

    if (
        typeof student.progress !== "number" ||
        student.progress < 0 ||
        student.progress > 100
    ) {
        throw new Error("Progress must be between 0 and 100.");
    }

    return true;
}

export function updateStudent(student, progress) {
    if (
        typeof progress !== "number" ||
        progress < 0 ||
        progress > 100
    ) {
        throw new Error("Progress must be between 0 and 100.");
    }

    return {
        ...student,
        progress,
    };
}

// domRenderer.js

export function renderStudent(student) {
    const nameElement = document.querySelector("#studentName");
    const courseElement = document.querySelector("#courseName");
    const progressElement = document.querySelector("#progress");

    if (
        !nameElement ||
        !courseElement ||
        !progressElement
    ) {
        throw new Error("Required DOM elements are missing.");
    }

    nameElement.textContent = student.name;
    courseElement.textContent = student.course;
    progressElement.textContent = `${student.progress}%`;
}

// main.js

import {
    calculateProgress,
    validateStudent,
    updateStudent,
} from "./courseService.js";

import { renderStudent } from "./domRenderer.js";

try {
    const student = {
        name: "Deb",
        course: "JavaScript",
        progress: 0,
    };

    const progress = calculateProgress(8, 10);

    console.assert(
        progress === 80,
        "Expected progress to be 80"
    );

    console.assert(
        calculateProgress(0, 0) === 0,
        "Expected zero progress when total is zero"
    );

    const updatedStudent = updateStudent(
        student,
        progress
    );

    console.assert(
        student.progress === 0,
        "Original student must remain unchanged"
    );

    validateStudent(updatedStudent);

    renderStudent(updatedStudent);

    console.log(
