function divide(a, b) {
    if (b === 0) {
        throw new Error("Cannot divide by zero.");
    }

    return a / b;
}

function calculate(a, operator, b) {
    if (
        typeof a !== "number" ||
        typeof b !== "number"
    ) {
        throw new Error(
            "Both values must be numbers."
        );
    }

    switch (operator) {
        case "+":
            return add(a, b);

        case "-":
            return subtract(a, b);

        case "*":
            return multiply(a, b);

        case "/":
            return divide(a, b);

        default:
            throw new Error(
                "Unsupported operator."
            );
    }
}

