// api.js

export async function loadCourse() {
    const response =
        await fetch("/api/course");

    if (!response.ok) {
        throw new Error(
            `Failed to load course (${response.status}).`
        );
    }

    const course =
        await response.json();

    if (
        !course ||
        !Array.isArray(course.modules)
    ) {
        throw new Error(
            "Invalid course data received."
        );
    }

    return course;
}

// progress.js

export function getAllLessons(course) {
    return course.modules.flatMap(
        (module) => Array.isArray(module.lessons)
            ? module.lessons
            : []
    );
}

export function calculateProgress(
    completedCount,
    totalCount
) {
    if (totalCount === 0) {
        return 0;
    }

    return Math.round(
        (completedCount / totalCount) * 100
    );
}

// state.js

export function createState() {
    return {
        course: null,
        selectedModuleId: null,
        selectedLessonId: null,
        completedLessons: new Set(),
    };
}

export function completeLesson(
    state,
    lessonId
) {
    state.completedLessons.add(lessonId);
}

export function saveProgress(state) {
    localStorage.setItem(
        "student-course-progress",
        JSON.stringify(
            [...state.completedLessons]
        )
    );
}

export function restoreProgress(state) {
    const saved =
        localStorage.getItem(
            "student-course-progress"
        );

    if (!saved) {
        return;
    }

    try {
        const ids = JSON.parse(saved);

        if (Array.isArray(ids)) {
            state.completedLessons =
                new Set(ids);
        }
    } catch {
        state.completedLessons =
            new Set();
    }
}

// renderer.js

export function renderCourse(
    course,
    state,
    elements,
    handlers
) {
    elements.courseTitle.textContent =
        course.title || "Untitled Course";

    elements.modules.innerHTML = "";

    if (!course.modules.length) {
        elements.modules.textContent =
            "No modules are available.";

        elements.lessons.textContent =
            "No lessons are available.";

        elements.lessonContent.textContent =
            "There is no lesson content to display.";

        return;
    }

    course.modules.forEach((module) => {
        const button =
            document.createElement("button");

        button.textContent =
            module.title || "Untitled Module";

        button.addEventListener(
            "click",
            () => handlers.selectModule(module.id)
        );

        elements.modules.appendChild(button);
    });

    renderLessons(
        course,
        state,
        elements,
        handlers
    );
}

export function renderLessons(
    course,
    state,
    elements,
    handlers
) {
    elements.lessons.innerHTML = "";

    const module =
        course.modules.find(
            (item) =>
                item.id === state.selectedModuleId
        );

    if (!module) {
        elements.lessons.textContent =
            "Select a module to view its lessons.";

        elements.lessonContent.textContent =
            "Select a lesson to view its content.";

        return;
    }

    const lessons =
        Array.isArray(module.lessons)
            ? module.lessons
            : [];

    if (!lessons.length) {
        elements.lessons.textContent =
            "No lessons are available.";

        elements.lessonContent.textContent =
            "There is no lesson content to display.";

        return;
    }

    lessons.forEach((lesson) => {
        const button =
            document.createElement("button");

        const completed =
            state.completedLessons.has(
                lesson.id
            );

        button.textContent =
            completed
                ? `✓ ${lesson.title}`
                : lesson.title;

        button.addEventListener(
            "click",
            () => handlers.selectLesson(lesson.id)
        );

        elements.lessons.appendChild(button);
    });

    renderLessonContent(
        course,
        state,
        elements,
        handlers
    );
}

