import { loadCourse } from "./api.js";

import {
    getAllLessons,
    calculateProgress,
} from "./progress.js";

import {
    createState,
    completeLesson,
    saveProgress,
    restoreProgress,
} from "./state.js";

import {
    renderCourse,
    renderLessons,
    renderLessonContent,
} from "./renderer.js";

const state = createState();

const elements = {
    courseTitle:
        document.querySelector("#courseTitle"),

    modules:
        document.querySelector("#modules"),

    lessons:
        document.querySelector("#lessons"),

    lessonContent:
        document.querySelector("#lessonContent"),

    progress:
        document.querySelector("#progress"),

    status:
        document.querySelector("#status"),
};

function renderProgress() {
    const total =
        getAllLessons(state.course).length;

    const percentage =
        calculateProgress(
            state.completedLessons.size,
            total
        );

    elements.progress.textContent =
        `Course Progress: ${percentage}%`;
}

function selectModule(moduleId) {
    state.selectedModuleId =
        moduleId;

    state.selectedLessonId =
        null;

    renderLessons(
        state.course,
        state,
        elements,
        handlers
    );
}

function selectLesson(lessonId) {
    state.selectedLessonId =
        lessonId;

    renderLessonContent(
        state.course,
        state,
        elements,
        handlers
    );
}

function handleCompleteLesson(lessonId) {
    completeLesson(
        state,
        lessonId
    );

    saveProgress(state);
    renderProgress();

    renderLessons(
        state.course,
        state,
        elements,
        handlers
    );
}

const handlers = {
    selectModule,
    selectLesson,
    completeLesson: handleCompleteLesson,
};

async function startApplication() {
    elements.status.textContent =
        "Loading course...";

    try {
        state.course =
            await loadCourse();

        restoreProgress(state);

        console.assert(
            calculateProgress(0, 0) === 0,
            "Zero lessons should produce 0%."
        );

        const before =
            state.completedLessons.size;

        completeLesson(
            state,
            "test-lesson"
        );

        completeLesson(
            state,
            "test-lesson"
        );

        console.assert(
            state.completedLessons.size ===
            before + 1,
            "Duplicate completion must not increase progress."
        );

        state.completedLessons.delete(
            "test-lesson"
        );

        elements.status.textContent =
            "";

        renderCourse(
            state.course,
            state,
            elements,
            handlers
        );

        renderProgress();
    } catch (error) {
        elements.status.textContent =
            `Unable to load course: ${error.message}`;
    }
}

startApplication();
